      "nl_concert": "Rock concert / club",
      "nl_concert_notes": "Permanent damage in minutes.",
      "nl_conversation": "Normal conversation",
      "nl_conversation_notes": "At 1 m.",
      "nl_gunshot": "Gunshot",
